/// Get OpenAPI schema.
async fn example_meta_get_schema() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: serde_json::Value = client.meta().get_schema().await?;
    println!("{:?}", result);
    Ok(())
}

/// Get ip address information.
async fn example_meta_get_ipinfo() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::IpAddrInfo = client.meta().get_ipinfo().await?;
    println!("{:?}", result);
    Ok(())
}

/// List all active announcements.
/// 
/// No authentication is required. Results are ordered newest first, with the announcement ID breaking ties.
/// 
/// **Parameters:**
/// 
/// - `limit: Option<u32>`: Maximum number of items returned by a single call
/// - `page_token: Option<String>`: Token returned by previous call to retrieve the subsequent page
async fn example_meta_get_announcements() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::AnnouncementResultsPage = client
        .meta()
        .get_announcements(Some(4 as u32), Some("some-string".to_string()))
        .await?;
    println!("{:?}", result);
    Ok(())
}


/// - OR -

/// Get a stream of results.
///
/// This allows you to paginate through all the items.
use futures_util::TryStreamExt;
async fn example_meta_get_announcements_stream() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let mut meta = client.meta();
    let mut stream = meta.get_announcements_stream(Some(4 as u32));
    loop {
        match stream.try_next().await {
            Ok(Some(item)) => {
                println!("{:?}", item);
            }
            Ok(None) => {
                break;
            }
            Err(err) => {
                return Err(err.into());
            }
        }
    }

    Ok(())
}

/// Get details of an API call.
/// 
/// This endpoint requires authentication by any Zoo user. It returns details of the requested API call for the user.
/// 
/// If the user is not authenticated to view the specified API call, then it is not returned.
/// 
/// Only Zoo employees can view API calls for other users.
/// 
/// **Parameters:**
/// 
/// - `id: uuid::Uuid`: The ID of the API call. (required)
use std::str::FromStr;
async fn example_api_calls_get() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::ApiCallWithPrice = client
        .api_calls()
        .get(uuid::Uuid::from_str(
            "d9797f8d-9ad6-4e08-90d7-2ec17e13471c",
        )?)
        .await?;
    println!("{:?}", result);
    Ok(())
}

/// Get an async operation.
/// 
/// Get the status and output of an async operation.
/// 
/// This endpoint requires authentication by any Zoo user. It returns details of the requested async operation for the user.
/// 
/// If the user is not authenticated to view the specified async operation, then it is not returned.
/// 
/// Only Zoo employees with the proper access can view async operations for other users.
/// 
/// **Parameters:**
/// 
/// - `id: uuid::Uuid`: The ID of the async operation. (required)
