/// Get CAD file bounding box.
/// 
/// Import the CAD file into the modeling engine and calculate its bounding box.
/// 
/// This endpoint returns the axis-aligned bounding box as a center and dimensions in the output units, using KittyCAD coordinates (+Z up, -Y forward).
/// 
/// This operation is always performed asynchronously, regardless of file size. The request returns the `id` of the operation. Use this `id` to get the status and bounding box from the `/async/operations/{id}` endpoint.
/// 
/// **Parameters:**
/// 
/// - `output_unit: Option<crate::types::UnitLength>`: The output unit for the bounding box.
/// - `src_format: crate::types::FileImportFormat`: The format of the file. (required)
async fn example_file_create_bounding_box() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::FileBoundingBox = client
        .file()
        .create_bounding_box(
            Some(kittycad::types::UnitLength::M),
            kittycad::types::FileImportFormat::Parasolid,
            &bytes::Bytes::from("some-string"),
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}

/// Get CAD file center of mass.
/// 
/// We assume any file given to us has one consistent unit throughout. We also assume the file is at the proper scale.
/// 
/// This endpoint returns the cartesian coordinate in the KittyCAD coordinate system (+Z up, -Y forward) using the requested measure units.
/// 
/// In the future, we will use the units inside the file if they are given and do any conversions if necessary for the calculation. But currently, that is not supported.
/// 
/// Get the center of mass of an object in a CAD file. If the file is larger than 25MB, it will be performed asynchronously.
/// 
/// If the operation is performed asynchronously, the `id` of the operation will be returned. You can use the `id` returned from the request to get status information about the async operation from the `/async/operations/{id}` endpoint.
/// 
/// **Parameters:**
/// 
/// - `output_unit: Option<crate::types::UnitLength>`: The output unit for the center of mass.
/// - `src_format: crate::types::FileImportFormat`: The format of the file. (required)
async fn example_file_create_center_of_mass() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::FileCenterOfMass = client
        .file()
        .create_center_of_mass(
            Some(kittycad::types::UnitLength::M),
            kittycad::types::FileImportFormat::Parasolid,
            &bytes::Bytes::from("some-string"),
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}

/// Convert CAD file from one format to another.
/// 
/// This takes a HTTP multipart body with these fields in any order:
/// 
/// - The input and output format options (as JSON), name is 'body'.  - The files to convert, in raw binary. Must supply filenames.
/// 
/// This starts a conversion job and returns the `id` of the operation. You can use the `id` returned from the request to get status information about the async operation from the `/async/operations/{id}` endpoint.
async fn example_file_create_conversion_options() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::FileConversion = client
        .file()
        .create_conversion_options(
            vec![kittycad::types::multipart::Attachment {
                name: "thing".to_string(),
                filepath: Some("myfile.json".into()),
                content_type: Some("application/json".to_string()),
                data: std::fs::read("myfile.json").unwrap(),
            }],
            &kittycad::types::ConversionParams {
                output_format: kittycad::types::OutputFormat3D::Fbx {
                    created: Some(chrono::Utc::now()),
                    storage: kittycad::types::FbxStorage::Binary,
                },
                src_format: kittycad::types::InputFormat3D::Acis {
                    coords: Some(kittycad::types::System {
                        forward: kittycad::types::AxisDirectionPair {
                            axis: kittycad::types::Axis::Z,
                            direction: kittycad::types::Direction::Negative,
                        },
                        up: kittycad::types::AxisDirectionPair {
                            axis: kittycad::types::Axis::Z,
                            direction: kittycad::types::Direction::Negative,
                        },
                    }),
                    split_closed_faces: true,
                },
            },
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}

/// Convert CAD file with defaults.
/// 
/// If you wish to specify the conversion options, use the `/file/conversion` endpoint instead.
/// 
/// Convert a CAD file from one format to another. If the file being converted is larger than 25MB, it will be performed asynchronously.
/// 
/// If the conversion is performed synchronously, the contents of the converted file (`output`) will be returned as a base64 encoded string.
/// 
/// If the operation is performed asynchronously, the `id` of the operation will be returned. You can use the `id` returned from the request to get status information about the async operation from the `/async/operations/{id}` endpoint.
/// 
/// **Parameters:**
/// 
/// - `output_format: crate::types::FileExportFormat`: The format the file should be converted to. (required)
/// - `src_format: crate::types::FileImportFormat`: The format of the file to convert. (required)
async fn example_file_create_conversion() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::FileConversion = client
        .file()
        .create_conversion(
            kittycad::types::FileExportFormat::Ply,
            kittycad::types::FileImportFormat::Parasolid,
            &bytes::Bytes::from("some-string"),
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}

/// Get CAD file density.
/// 
/// We assume any file given to us has one consistent unit throughout. We also assume the file is at the proper scale.
/// 
/// This endpoint assumes if you are giving a material mass in a specific mass units, we return a density in mass unit per cubic measure unit.
/// 
/// In the future, we will use the units inside the file if they are given and do any conversions if necessary for the calculation. But currently, that is not supported.
/// 
/// Get the density of an object in a CAD file. If the file is larger than 25MB, it will be performed asynchronously.
/// 
/// If the operation is performed asynchronously, the `id` of the operation will be returned. You can use the `id` returned from the request to get status information about the async operation from the `/async/operations/{id}` endpoint.
/// 
/// **Parameters:**
/// 
/// - `material_mass: f64`: The material mass. (required)
/// - `material_mass_unit: Option<crate::types::UnitMass>`: The unit of the material mass.
/// - `output_unit: Option<crate::types::UnitDensity>`: The output unit for the density.
/// - `src_format: crate::types::FileImportFormat`: The format of the file. (required)
async fn example_file_create_density() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::FileDensity = client
        .file()
        .create_density(
            3.14 as f64,
            Some(kittycad::types::UnitMass::Kg),
            Some(kittycad::types::UnitDensity::KgM3),
            kittycad::types::FileImportFormat::Parasolid,
            &bytes::Bytes::from("some-string"),
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}

