/// List API calls for a user.
/// 
/// This endpoint requires authentication by any Zoo user. It returns the API calls for the authenticated user if "me" is passed as the user id.
/// 
/// Alternatively, you can use the `/user/api-calls` endpoint to get the API calls for your user.
/// 
/// If the authenticated user is a Zoo employee, then the API calls are returned for the user specified by the user id.
/// 
/// The API calls are returned in order of creation, with the most recently created API calls first.
/// 
/// **Parameters:**
/// 
/// - `id: &'astr`: The user's identifier (uuid or email). (required)
/// - `limit: Option<u32>`: Maximum number of items returned by a single call
/// - `page_token: Option<String>`: Token returned by previous call to retrieve the subsequent page
/// - `sort_by: Option<crate::types::CreatedAtSortMode>`
async fn example_api_calls_list_for_user() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let result: kittycad::types::ApiCallWithPriceResultsPage = client
        .api_calls()
        .list_for_user(
            "some-string",
            Some(4 as u32),
            Some("some-string".to_string()),
            Some(kittycad::types::CreatedAtSortMode::CreatedAtDescending),
        )
        .await?;
    println!("{:?}", result);
    Ok(())
}


/// - OR -

/// Get a stream of results.
///
/// This allows you to paginate through all the items.
use futures_util::TryStreamExt;
async fn example_api_calls_list_for_user_stream() -> anyhow::Result<()> {
    let client = kittycad::Client::new_from_env();
    let mut api_calls = client.api_calls();
    let mut stream = api_calls.list_for_user_stream(
        "some-string",
        Some(4 as u32),
        Some(kittycad::types::CreatedAtSortMode::CreatedAtDescending),
    );
    loop {
        match stream.try_next().await {
            Ok(Some(item)) => {
                println!("{:?}", item);
            }
            Ok(None) => {
                break;
            }
            Err(err) => {
                return Err(err.into());
            }
        }
    }

    Ok(())
}

